arguments.command:
cd /tmp/sv-7840c65c55894a0a959b4ac894d5a7ca && \
# Use nm on dynamic symbols with sizes, sort by address, and find accurate matches
nm -D --defined-only -S mono_debug 2>/dev/null | sort -k1 | awk '
{
  addr = strtonum("0x" $1)
  size = ($3 ~ /^[0-9a-fA-F]+$/) ? strtonum("0x" $2) : 0
  if (NF == 4) { name = $4 }
  else { name = $3 }
  syms[n] = name; addrs[n] = addr; sizes[n] = size; n++
}
END {
  split("0x222098 0x2241ac 0x1abc80 0x1abd14 0x16dfa4 0x16db6c 0x16de04", targets, " ")
  for (t in targets) {
    target = strtonum(targets[t])
    best = -1; best_addr = 0
    for (i = 0; i < n; i++) {
      if (addrs[i] <= target && addrs[i] > best_addr) {
        best = i; best_addr = addrs[i]
      }
    }
    if (best >= 0) {
      off = target - best_addr
      in_range = (sizes[best] > 0 && off < sizes[best]) ? "" : " (nearest, may be inaccurate)"
      printf "%s -> %s+0x%x%s\n", targets[t], syms[best], off, in_range
    }
  }
}' 2>/dev/null

